import{c as n,$ as l,Q as r,j as a,g as e,o,n as i,m as d}from"./chunks/framework.Ce_49mA8.js";const k=JSON.parse('{"title":"Лицензии и ограничения","description":"Практическое руководство по тарифам ОмниКрафт ЕРП, лимиту ознакомительной версии, криптографической защите и управлению устройствами.","frontmatter":{"title":"Лицензии и ограничения","description":"Практическое руководство по тарифам ОмниКрафт ЕРП, лимиту ознакомительной версии, криптографической защите и управлению устройствами.","datePublished":"2026-10-28","dateModified":"2026-11-17","order":23},"headers":[],"relativePath":"ru/docs/licenses.md","filePath":"ru/docs/licenses.md","lastUpdated":1794873600000}'),h={name:"ru/docs/licenses.md"},c={id:"лицензии-и-ограничения-честныи-триал-тарифные-планы-и-автономная-защита",tabindex:"-1"};function g(p,t,u,x,y,b){const s=l("DocIcon");return r(),a("div",null,[e("h1",c,[o(s,{name:"licenses"}),t[0]||(t[0]=i(" Лицензии и ограничения: Честный триал, тарифные планы и автономная защита ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#лицензии-и-ограничения-честныи-триал-тарифные-планы-и-автономная-защита","aria-label":'Permalink to "Лицензии и ограничения: Честный триал, тарифные планы и автономная защита"'},"​",-1))]),t[2]||(t[2]=d('<p>Для мастера, владельца сервисного центра или руководителя небольшого ремесленного производства программное обеспечение — это рабочий станок, а не повод для непредвиденных ежемесячных трат. Если разработчик облачной платформы решит изменить условия, заблокировать учетную запись или отключить серверы, предприятие рискует мгновенно потерять доступ к собственной клиентской базе и финансовой истории.</p><p>В ОмниКрафт ЕРП изначально заложена принципиально иная архитектурная модель:</p><ul><li><strong>Локальный суверенитет:</strong> программа работает как автономное десктопное приложение для Windows. База данных хранится исключительно на физическом диске Вашего компьютера, гарантируя 100% приватность коммерческих тайн;</li><li><strong>Честный ознакомительный период:</strong> программа не урезает инструменты планирования, не скрывает складские таблицы и не прячет отчеты об управленческом балансе. Вы получаете полностью рабочий комплекс для спокойного тестирования в реальных цеховых условиях;</li><li><strong>Прозрачная шкала развития:</strong> коммерческая лицензия снимает единственное ограничение ознакомительной версии и открывает возможности масштабирования по мере роста оборотов вашего дела.</li></ul><hr><h2 id="три-тарифных-плана" tabindex="-1">Три тарифных плана <a class="header-anchor" href="#три-тарифных-плана" aria-label="Permalink to &quot;Три тарифных плана&quot;">​</a></h2><p>Система предлагает понятную градацию возможностей без скрытых условий и навязанных микроплатежей:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Возможности и контуры учета</th><th style="text-align:center;">🆓 Ознакомительный (0 ₽)</th><th style="text-align:center;">🥈 Стандартный</th><th style="text-align:center;">👑 Профессиональный («ПРО»)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Базовые контуры мастерской</strong> (активы, склад материалов, калькулятор, верстак, склад изделий, витрина)</td><td style="text-align:center;">Полный доступ</td><td style="text-align:center;">Полный доступ</td><td style="text-align:center;">Полный доступ</td></tr><tr><td style="text-align:left;"><strong>Финансовые контуры предприятия</strong> (касса и движение денег, управленческий баланс, аналитика выручки)</td><td style="text-align:center;">Полный доступ</td><td style="text-align:center;">Полный доступ</td><td style="text-align:center;">Полный доступ</td></tr><tr><td style="text-align:left;"><strong>Лимит на проведение розничных продаж</strong></td><td style="text-align:center;">До 20 чеков</td><td style="text-align:center;">Без ограничений</td><td style="text-align:center;">Без ограничений</td></tr><tr><td style="text-align:left;"><strong>Резервное копирование и безопасность</strong> (защита транзакций, схема архивации баз)</td><td style="text-align:center;">Полный доступ</td><td style="text-align:center;">Полный доступ</td><td style="text-align:center;">Полный доступ</td></tr><tr><td style="text-align:left;"><strong>Количество рабочих пространств</strong></td><td style="text-align:center;">1 активное (смена через архив)</td><td style="text-align:center;">1 активное (смена через архив)</td><td style="text-align:center;">Неограниченно (мультипространства)</td></tr><tr><td style="text-align:left;"><strong>Возврат предприятий из архива</strong></td><td style="text-align:center;">Через лицензию «ПРО»</td><td style="text-align:center;">Через лицензию «ПРО»</td><td style="text-align:center;">Мгновенно в 1 клик</td></tr><tr><td style="text-align:left;"><strong>Сквозной раздел «Мой капитал»</strong> (учет личных счетов, портфеля и имущества)</td><td style="text-align:center;">Недоступно</td><td style="text-align:center;">Недоступно</td><td style="text-align:center;">Полный доступ</td></tr><tr><td style="text-align:left;"><strong>Маркетплейс специализированных модулей</strong></td><td style="text-align:center;">Недоступно</td><td style="text-align:center;">Доступна докупка</td><td style="text-align:center;">Доступна докупка</td></tr></tbody></table><hr><h2 id="архитектура-рабочих-пространств-правила-для-тарифов" tabindex="-1">Архитектура рабочих пространств: правила для тарифов <a class="header-anchor" href="#архитектура-рабочих-пространств-правила-для-тарифов" aria-label="Permalink to &quot;Архитектура рабочих пространств: правила для тарифов&quot;">​</a></h2><p>ОмниКрафт ЕРП позволяет гибко настраивать профиль предприятия («Производство» или «Услуги») уже при первом запуске:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"></rect><path d="M3 9h18"></path><path d="M9 21V9"></path></svg></span><span><strong>Одно активное предприятие на тарифах «Ознакомительный» и «Стандарт»:</strong> лицензия рассчитана на ведение одного полноценного бизнеса (например, кожевенной мастерской или мастерской по ремонту часов).</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 8v13H3V8"></path><path d="M1 3h22v5H1z"></path><path d="M10 12h4"></path></svg></span><span><strong>Смена направления через архив:</strong> если профиль деятельности изменился или Вы решили начать учет заново, текущее предприятие переводится в архив, после чего создается новое рабочее пространство.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><span><strong>Защитное окно отмены случайной архивации:</strong> при случайном нажатии кнопки архивации в боковом меню действует 15-минутный период бесплатного возврата предприятия в активное состояние.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg></span><span><strong>Почему разархивирование требует тарифа «ПРО»:</strong> неограниченное извлечение архивов на тарифе «Стандарт» позволило бы попеременно вести десятки независимых бизнесов в рамках одной базовой лицензии. Для одновременного параллельного учета нескольких направлений предназначен профессиональный тариф.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" x2="12" y1="15" y2="3"></line></svg></span><span><strong>Свобода данных:</strong> из архивного хранилища в любой момент доступно бесплатное скачивание резервной копии базы данных и табличных отчетов без покупки лицензий.</span></li></ul><hr><h2 id="как-работает-ограничение-ознакомительнои-версии-20-продаж" tabindex="-1">Как работает ограничение ознакомительной версии (20 продаж) <a class="header-anchor" href="#как-работает-ограничение-ознакомительнои-версии-20-продаж" aria-label="Permalink to &quot;Как работает ограничение ознакомительной версии (20 продаж)&quot;">​</a></h2><p>Ознакомительная версия ОмниКрафт ЕРП принципиально отличается от демонстрационных программ с урезанными функциями. Вам доступны абсолютно все аналитические таблицы, технологические карты, расчет норм расхода сырья и складские остатки.</p><p>Единственная граница триала установлена в <strong>самой финальной точке производственного конвейера</strong> — при регистрации факта получения денег от покупателя.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Приемка сырья] ➔ [Рецепт изделия] ➔ [Выпуск на верстаке] ➔ [Кассовый чек]</span></span>\n<span class="line"><span>       ✅                 ✅                   ✅             ⚠️ До 20 чеков</span></span></code></pre></div><h3 id="что-происходит-при-достижении-порога" tabindex="-1">Что происходит при достижении порога <a class="header-anchor" href="#что-происходит-при-достижении-порога" aria-label="Permalink to &quot;Что происходит при достижении порога&quot;">​</a></h3><p>Как только счетчик оформленных чеков во вкладке «Продажи» достигает <strong>20 операций</strong>, программа автоматически переводит контур фиксации выручки в защищенный режим только для чтения:</p><ul><li><strong>Блокировка проведения сделок:</strong> кнопка <strong>«Провести продажу»</strong> в кассовом терминале и кнопка <strong>«Завершить заказ»</strong> при выпуске готовой партии в производство становятся неактивными. В верхней части экрана появляется информационная панель с предложением активировать лицензию;</li><li><strong>Полное сохранение доступа ко всей системе:</strong> Вы можете свободно анализировать отчеты, вносить материалы на склад, создавать новые технологические рецепты, просматривать графики рентабельности и создавать резервные копии;</li><li><strong>Сохранность наработанной базы:</strong> ни одна строчка данных не удаляется. При активации коммерческого ключа все лимиты мгновенно снимаются, и работа продолжается без потери истории.</li></ul><h3 id="экономическии-предохранитель-от-обхода" tabindex="-1">Экономический предохранитель от обхода <a class="header-anchor" href="#экономическии-предохранитель-от-обхода" aria-label="Permalink to &quot;Экономический предохранитель от обхода&quot;">​</a></h3><p>В традиционных программах пользователи нередко пытаются сбросить ознакомительный счетчик, удаляя старые записи. В ОмниКрафт ЕРП подобные действия <strong>лишены экономического смысла</strong>.</p><p>Управленческий учет ценен исключительно непрерывностью исторической цепочки данных. Если мастер попытается вручную очистить базу продаж, чтобы обнулить счетчик чеков, система неизбежно зафиксирует разрыв связей, что приведет к разрушению:</p><ol><li><strong>Управленческого баланса (вкладка «Капитал»):</strong> искажаются показатели собственного капитала и чистых активов мастерской;</li><li><strong>Кассовой истории (вкладка «ДДС»):</strong> реальный остаток наличных денег и средств на расчетных счетах перестанет сходиться с учетным;</li><li><strong>Партионного списания сырья по методу первых партий (ФИФО):</strong> сбивается себестоимость остатков готовой продукции на складе;</li><li><strong>Аналитики рентабельности:</strong> обнуляются графики выручки и расчет точки безубыточности.</li></ol><p>Таким образом, предприниматель сам экономически заинтересован в чистоте и непрерывности своей учетной базы. Покупка лицензии — это не просто снятие ограничения программы, а инвестиция в сохранность цифрового фундамента собственного бизнеса.</p><hr><h2 id="автономная-криптографическая-защита-и-конфиденциальность-нулевои-сбор-персональных-данных" tabindex="-1">Автономная криптографическая защита и конфиденциальность (нулевой сбор персональных данных) <a class="header-anchor" href="#автономная-криптографическая-защита-и-конфиденциальность-нулевои-сбор-персональных-данных" aria-label="Permalink to &quot;Автономная криптографическая защита и конфиденциальность (нулевой сбор персональных данных)&quot;">​</a></h2><p>ОмниКрафт ЕРП — локальное настольное приложение. Программа принципиально не отправляет Ваши финансовые операции на удаленные серверы. Проверка подлинности лицензионного ключа выполняется <strong>на 100% автономно</strong> без обязательного подключения к сети.</p><table class="craft-matrix-table"><thead><tr><th style="width:50%;">Сервер лицензирования (Онлайн-генерация)</th><th style="width:50%;">Компьютер мастера (Офлайн-валидация)</th></tr></thead><tbody><tr><td><ol class="craft-list-steps" style="margin:0;"><li><div><strong>Отпечаток ПК:</strong> Приём обезличенного хеша оборудования.</div></li><li><div><strong>Цифровая подпись:</strong> Подписание закрытым криптографическим ключом.</div></li><li><div><strong>Выдача ключа:</strong> Формирование автономного лицензионного сертификата.</div></li></ol></td><td><ol class="craft-list-steps" style="margin:0;"><li><div><strong>Ввод ключа:</strong> Вставка сертификата в окне «Лицензия».</div></li><li><div><strong>Проверка открытым ключом:</strong> Локальная математическая валидация.</div></li><li><div><strong>Мгновенная разблокировка:</strong> Запуск всех функций без связи с интернетом.</div></li></ol></td></tr></tbody></table><h3 id="_1-аппаратныи-отпечаток-компьютера" tabindex="-1">1. Аппаратный отпечаток компьютера <a class="header-anchor" href="#_1-аппаратныи-отпечаток-компьютера" aria-label="Permalink to &quot;1. Аппаратный отпечаток компьютера&quot;">​</a></h3><p>При первом запуске приложение вычисляет уникальный цифровой слепок оборудования на основе параметров материнской платы и системного реестра операционной системы:</p><ul><li><strong>Мгновенный отклик:</strong> процедура определения идентификатора занимает менее 0.1 миллисекунды и не замедляет старт программы;</li><li><strong>Абсолютная конфиденциальность:</strong> отпечаток представляет собой обезличенную шестнадцатеричную строку (например, <code>A1B2-C3D4-E5F6-G7H8</code>). Он не содержит имен учетных записей, адресов электронной почты, паролей, сетевых адресов или названий файлов;</li><li><strong>Соответствие 152-ФЗ:</strong> архитектура биллинга полностью исключает сбор и обработку персональных данных.</li></ul><h3 id="_2-асимметричное-шифрование-с-открытым-ключом" tabindex="-1">2. Асимметричное шифрование с открытым ключом <a class="header-anchor" href="#_2-асимметричное-шифрование-с-открытым-ключом" aria-label="Permalink to &quot;2. Асимметричное шифрование с открытым ключом&quot;">​</a></h3><p>Для предотвращения взлома и генерации поддельных ключей применяется криптография с открытым ключом:</p><ul><li><strong>Открытый ключ в программе:</strong> скомпилирован непосредственно в исполняемый файл приложения. Он способен исключительно <em>проверять</em> подлинность цифровой подписи, но математически не способен создать новую;</li><li><strong>Закрытый ключ на защищенном сервере:</strong> хранится в изолированной серверной среде и никогда не попадает в дистрибутив программы.</li></ul><h3 id="_3-анонимныи-лицензионныи-токен" tabindex="-1">3. Анонимный лицензионный токен <a class="header-anchor" href="#_3-анонимныи-лицензионныи-токен" aria-label="Permalink to &quot;3. Анонимный лицензионный токен&quot;">​</a></h3><p>При приобретении лицензии на сайте покупателю не требуется проходить обязательную регистрацию с паспортом или номером телефона. Система генерирует анонимный токен вида <code>LIC-XXXX-XXXX-XXXX</code>, за которым на сервере закрепляется только тип лицензии и список разрешенных отпечатков оборудования.</p><p>Каждая коммерческая лицензия поддерживает активацию <strong>до 5 рабочих компьютеров одновременно</strong> (например, стационарный компьютер в цеху, ноутбук руководителя и рабочее место приемщика заказов).</p><hr><h2 id="управление-устроиствами-и-самообслуживание" tabindex="-1">Управление устройствами и самообслуживание <a class="header-anchor" href="#управление-устроиствами-и-самообслуживание" aria-label="Permalink to &quot;Управление устройствами и самообслуживание&quot;">​</a></h2><p>Если рабочий ноутбук вышел из строя или мастер приобрел новый рабочий компьютер, лицензию не придется покупать повторно.</p><p>Система самообслуживания позволяет освободить слот устройства двумя удобными способами:</p><div class="craft-window-frame" data-title="Устройства лицензии (2 из 5 занято)"><div style="padding:1rem 1.25rem;"><table class="craft-matrix-table" style="margin:0;"><thead><tr><th style="width:45%;">Устройство</th><th style="width:35%;">Идентификатор оборудования</th><th style="width:20%;">Статус</th></tr></thead><tbody><tr><td><strong>Рабочий ноутбук</strong><br><span style="opacity:0.7;font-size:0.85em;">Текущий компьютер</span></td><td><code>A1B2-C3D4-E5F6-G7H8</code></td><td><span style="color:#10b981;font-weight:600;">● Активно</span></td></tr><tr><td><strong>Старый цеховой ПК</strong><br><span style="opacity:0.7;font-size:0.85em;">Резервное рабочее место</span></td><td><code>F9E8-D7C6-B5A4-9988</code></td><td><span style="opacity:0.8;">[ Отвязать ]</span></td></tr></tbody></table></div></div><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="20" height="14" x="2" y="3" rx="2"></rect><line x1="8" y1="21" x2="16" y2="21"></line><line x1="12" y1="17" x2="12" y2="21"></line></svg></span><span><strong>Встроенное окно управления устройствами:</strong> в окне «Настройки программы» нажмите кнопку <strong>«Устройства»</strong>. Откроется список всех привязанных компьютеров с возможностью отвязать неиспользуемый компьютер в один клик.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg></span><span><strong>Портал самообслуживания на сайте:</strong> если компьютер сгорел и доступ к программе утерян, перейдите в раздел управления лицензиями на официальном сайте, укажите свой токен `LIC-XXXX-XXXX-XXXX` и удалите старый компьютер из слотов без ожидания ответа службы поддержки.</span></li></ul><hr><h2 id="пошаговое-руководство-активация-ключа-в-программе" tabindex="-1">Пошаговое руководство: Активация ключа в программе <a class="header-anchor" href="#пошаговое-руководство-активация-ключа-в-программе" aria-label="Permalink to &quot;Пошаговое руководство: Активация ключа в программе&quot;">​</a></h2><p>Процедура активации занимает менее одной минуты и не требует технических навыков:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><span><strong>Шаг 1: Скопируйте аппаратный отпечаток.</strong> Откройте диалоговое окно «Настройки» через главное меню программы. В карточке «Управление лицензией» найдите строку с отпечатком оборудования и нажмите кнопку копирования рядом с ней.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4Z"></path><path d="M3 6h18"></path><path d="M16 10a4 4 0 0 1-8 0"></path></svg></span><span><strong>Шаг 2: Получите ключ или токен.</strong> При оформлении лицензии на сайте вставьте скопированный отпечаток в форму заказа. Система выдаст Вам лицензионный токен или готовый текстовый ключ.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Шаг 3: Активируйте систему.</strong> Вставьте полученный ключ или токен в поле ввода и нажмите кнопку <strong>«Активировать»</strong>.</span></li></ul><div class="tip custom-block"><p class="custom-block-title">Динамический статус в заголовке программы</p><p>Сразу после успешной проверки ключа перезапуск программы не требуется. Заголовок главного окна Windows мгновенно обновится: вместо ознакомительного статуса появится отметка активной лицензии: <em>ОмниКрафт ЕРП (Стандарт)</em> или <em>ОмниКрафт ЕРП (ПРО)</em>, а также число подключенных отраслевых модулей.</p></div><hr><h2 id="вопросы-и-ответы-мастера" tabindex="-1">Вопросы и ответы мастера <a class="header-anchor" href="#вопросы-и-ответы-мастера" aria-label="Permalink to &quot;Вопросы и ответы мастера&quot;">​</a></h2><h3 id="требуется-ли-постоянное-подключение-к-интернету-для-проверки-лицензии" tabindex="-1">Требуется ли постоянное подключение к интернету для проверки лицензии? <a class="header-anchor" href="#требуется-ли-постоянное-подключение-к-интернету-для-проверки-лицензии" aria-label="Permalink to &quot;Требуется ли постоянное подключение к интернету для проверки лицензии?&quot;">​</a></h3><p>Нет. Вся проверка подлинности ключа выполняется встроенным криптографическим модулем локально на Вашем компьютере. Интернет необходим только в момент первоначальной онлайн-активации по токену. Вся дальнейшая многолетняя работа протекает на 100% автономно в режиме офлайн.</p><h3 id="что-произоидет-с-накопленными-данными-при-окончании-срока-подписки" tabindex="-1">Что произойдет с накопленными данными при окончании срока подписки? <a class="header-anchor" href="#что-произоидет-с-накопленными-данными-при-окончании-срока-подписки" aria-label="Permalink to &quot;Что произойдет с накопленными данными при окончании срока подписки?&quot;">​</a></h3><p>Все Ваши данные, технологические карты, складские остатки и история взаиморасчетов остаются в полной сохранности на жестком диске Вашего компьютера. Программа никогда не блокирует доступ к архивным сведениям и не удаляет записи. При завершении периода подписки система лишь возвращается в режим чтения кассы до момента продления лицензии.</p><h3 id="на-скольких-компьютерах-можно-использовать-один-лицензионныи-ключ" tabindex="-1">На скольких компьютерах можно использовать один лицензионный ключ? <a class="header-anchor" href="#на-скольких-компьютерах-можно-использовать-один-лицензионныи-ключ" aria-label="Permalink to &quot;На скольких компьютерах можно использовать один лицензионный ключ?&quot;">​</a></h3><p>Каждая лицензия включает 5 независимых аппаратных слотов. Вы можете установить программу на рабочий ноутбук, стационарный моноблок в мастерской и домашний компьютер. Если один из компьютеров заменяется, освободите слот через меню «Устройства» и активируйте новый компьютер.</p><h3 id="как-переити-с-тарифа-«стандарт»-на-тариф-«про»" tabindex="-1">Как перейти с тарифа «Стандарт» на тариф «ПРО»? <a class="header-anchor" href="#как-переити-с-тарифа-«стандарт»-на-тариф-«про»" aria-label="Permalink to &quot;Как перейти с тарифа «Стандарт» на тариф «ПРО»?&quot;">​</a></h3><p>Повторно оплачивать полную стоимость программы не требуется. В окне настроек лицензии нажмите кнопку <strong>«Улучшить до ПРО»</strong>: откроется страница оплаты с автоматическим пересчетом стоимости перехода (доплата разницы между тарифами).</p>',58))])}const v=n(h,[["render",g]]);export{k as __pageData,v as default};
